 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    # Select the color occurring in the largest number of separate 4-connected
    # components: these isolated marks indicate where to stamp the motif.
    seen = set()
    components = {}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen:
                continue
            stack = [(r,c)]
            seen.add((r,c))
            while stack:
                y,x = stack.pop()
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            components[color] = components.get(color,0) + 1
    marker = max(components, key=components.get)
    marks = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, marker)]
    r0,r1=min(r for r,c in pts),max(r for r,c in pts)
    c0,c1=min(c for r,c in pts),max(c for r,c in pts)
    motif=[row[c0:c1+1] for row in grid[r0:r1+1]]
    ar,ac=(r1-r0)//2,(c1-c0)//2
    out=[row[:] for row in grid]
    for mr,mc in marks:
        top,left=mr-ar,mc-ac
        for y,row in enumerate(motif):
            for x,val in enumerate(row):
                yy,xx=top+y,left+x
                if 0<=yy<h and 0<=xx<w:
                    out[yy][xx]=val
    return out
